<script setup lang="ts">
import {computed,onBeforeUnmount,ref} from 'vue';
import {ArrowLeft,ArrowRight,ClipboardList,LoaderCircle,RefreshCw,Search} from 'lucide-vue-next';
import type {MacroAuditPage} from '../../../../packages/shared/src/access-management';
import {ApiError,queryString,request} from '../api';
import {useAppStore} from '../stores/app';
import '../styles/access-management.css';
import {watchCredentialContext} from '../access-context';
const app=useAppStore(),state=ref<MacroAuditPage>(),loading=ref(false),error=ref(''),action=ref(''),actor=ref(''),project=ref(''),from=ref(''),to=ref(''),page=ref(1);let generation=0;
const pages=computed(()=>Math.max(1,Math.ceil((state.value?.total??0)/(state.value?.pageSize??30))));
const titles:Record<string,string>={'project.fields_updated':'修改样本字段展示或约束','project.labels_updated':'修改项目标签','project.templates_adopted':'采用项目标签模板','project.readme_updated':'修改数据集说明','project.branch_created':'创建分支','project.merged':'合并项目分支','project.version_restored':'恢复数据版本','governance.updated':'维护标签与模板配置','dataset.initialized':'初始化数据集','dataset.imported':'导入样本','release.updated':'修改发布候选','release.withdrawn':'撤回发布版本','release.latest_changed':'切换最新稳定版','operation.reconciled':'核对故障操作结果','system.maintenance_started':'开始停写维护','system.maintenance_finished':'恢复写入','project.created':'创建数据集项目','project.removed':'移除数据集项目','project.restored':'恢复数据集项目','project.updated':'修改项目信息','release.published':'发布数据集','release.created':'创建发布版本','release.shared':'创建发布分享','release.share_revoked':'撤销发布分享','access.granted':'发放项目访问权限','access.role_changed':'变更项目角色或能力','access.revoked':'撤销项目权限','identity.granted':'发放实例权限','token.rotated':'轮换访问令牌','token.revoked':'撤销访问令牌','template.published':'发布标签模板','template.created':'创建标签模板','template.updated':'修改标签模板','dimension.created':'创建标签维度','dimension.updated':'修改标签维度','dimension.published':'发布标签维度','governance.maintainer_changed':'变更标签维护人员','dataset.fields_updated':'修改样本字段配置','schema.adopted':'采用标签模板','merge.completed':'完成分支合并','readme.updated':'修改数据集说明'};
const date=(value:string)=>new Date(value).toLocaleString();
async function load(){const current=++generation;loading.value=true;error.value='';try{const value=await request<MacroAuditPage>('/audit-events'+queryString({page:page.value,pageSize:30,action:action.value||undefined,actor:actor.value.trim()||undefined,project:project.value.trim()||undefined,from:from.value?new Date(from.value).toISOString():undefined,to:to.value?new Date(to.value).toISOString():undefined}));if(current===generation)state.value=value;}catch(cause){if(current===generation){error.value=(cause as Error).message;if(cause instanceof ApiError&&[401,403].includes(cause.status))state.value=undefined;}}finally{if(current===generation)loading.value=false;}}
function search(){page.value=1;void load();}function reset(){action.value='';actor.value='';project.value='';from.value='';to.value='';page.value=1;void load();}function paginate(value:number){page.value=value;void load();}
watchCredentialContext(()=>app.status?.identity,()=>{state.value=undefined;error.value='';page.value=1;void load();});onBeforeUnmount(()=>{generation++;});
</script>
<template>
  <section class="access-management" aria-label="全局操作日志">
    <header class="management-heading"><div><span class="eyebrow">WORKSPACE ACTIVITY</span><h1>操作日志</h1><p>查看项目、发布、权限和重要配置的宏观变更，了解整个工作空间的动态。</p></div><button class="btn" :disabled="loading" @click="load"><RefreshCw :size="15"/>刷新</button></header>
    <p class="notice management-access-note"><ClipboardList :size="17"/><span>仅实例管理员与授权审计人员可见。日志不展示原始样本、令牌或查询问题；样本级修改继续通过项目版本与差异核对。默认保留{{state?.retentionDays??90}}天。</span></p>
    <p v-if="error" class="error-state" role="alert">{{error}} <button class="btn btn-ghost" @click="load">重新读取</button></p>
    <form class="management-panel" @submit.prevent="search"><div class="management-filters"><label>操作类型<select v-model="action"><option value="">全部操作</option><option v-for="item in state?.actions??[]" :key="item" :value="item">{{titles[item]??item}}</option></select></label><label>人员<input v-model="actor" maxlength="160" placeholder="姓名或完整人员ID…"/></label><label>项目<input v-model="project" maxlength="250" placeholder="命名空间/项目…"/></label></div><div class="management-filters"><label>开始时间<input v-model="from" type="datetime-local"/></label><label>结束时间<input v-model="to" type="datetime-local"/></label><button class="btn btn-primary" :disabled="loading"><Search :size="15"/>筛选</button><button class="btn btn-ghost" type="button" :disabled="loading" @click="reset">清除筛选</button></div></form>
    <section class="management-panel"><header class="management-list-heading"><div><h2>工作空间动态</h2><p>按发生时间从新到旧排列。审计入口不会自动补写过去没有记录的事件。</p></div><strong v-if="state">{{state.total}} 条</strong></header>
      <p v-if="loading&&!state" class="management-loading" role="status"><LoaderCircle class="spin" :size="18"/>正在读取操作记录…</p>
      <div v-if="state?.items.length" class="management-table-scroll"><table><thead><tr><th>时间</th><th>人员</th><th>操作</th><th>项目 / 对象</th><th>核对信息</th></tr></thead><tbody><tr v-for="event in state.items" :key="event.id"><td>{{date(event.at)}}<small class="mono" :title="event.id">{{event.id.slice(0,8)}}…</small></td><td>{{event.actor.name}}<small>{{event.actor.kind==='owner'?'实例管理员':event.actor.kind==='collaborator'?'独立协作者':'访客'}}</small></td><td>{{titles[event.action]??event.action}}<small class="mono">{{event.action}}</small></td><td><RouterLink v-if="event.repository" :to="'/repos/'+encodeURIComponent(event.repository.namespace)+'/'+encodeURIComponent(event.repository.repo)+'/overview'">{{event.repository.namespace}}/{{event.repository.repo}}</RouterLink><span v-else>工作空间</span><small v-if="event.targetId" class="mono">{{event.targetId}}</small></td><td><details v-if="event.details&&Object.keys(event.details).length" class="management-event-details"><summary>查看元数据</summary><dl><template v-for="(value,key) in event.details" :key="key"><dt>{{key}}</dt><dd>{{value===null?'—':String(value)}}</dd></template></dl></details><span v-else class="muted">—</span></td></tr></tbody></table></div>
      <p v-else-if="state" class="management-empty">{{action||actor||project||from||to?'当前条件下没有操作记录。':'尚无操作记录。后续项目、发布和权限等操作将在此记录。'}}</p>
      <footer v-if="state" class="management-pagination"><span>第{{state.page}} / {{pages}}页 · 共{{state.total}}条</span><div><button class="btn" :disabled="loading||page<=1" @click="paginate(page-1)"><ArrowLeft :size="14"/>上一页</button><button class="btn" :disabled="loading||page>=pages" @click="paginate(page+1)">下一页<ArrowRight :size="14"/></button></div></footer>
    </section>
  </section>
</template>
